// Generates lib/src/bindings.g.dart from the sound's C header
// (crates/fynkel_audio_ffi/include/fynkel_audio.h, itself generated by
// cbindgen).
//
//   dart run tool/ffigen.dart
//
// CI runs this and fails when the result differs from the committed file.

import 'dart:io';

import 'package:ffigen/ffigen.dart';

Future<void> main() async {
  final root = Platform.script.resolve('../');
  final header = root.resolve('../../crates/fynkel_audio_ffi/include/fynkel_audio.h');
  final generator = FfiGenerator(
    input: Input(
      entryPoints: [header],
      // Only the header's own declarations, not those of the system
      // headers it includes.
      include: (uri) => uri == header,
    ),
    output: Output(
      dart: DartOutput(path: root.resolve('lib/src/bindings.g.dart')),
      preamble:
          '// Generated by tool/ffigen.dart from crates/fynkel_audio_ffi/include/fynkel_audio.h. Do not edit.\n'
          '// ignore_for_file: type=lint, unused_field',
      style: const NativeExternalBindings(assetId: 'package:fynkel_audio/fynkel_audio'),
    ),
    visitors: [
      Visitor(
        // Every call is short, decoding aside, which runs on a helper
        // isolate: a leaf call is fine for all of them.
        func: (node) {
          if (!node.originalName.startsWith('fa_')) return;
          node.isIncluded = true;
          node.isLeaf = true;
        },
        struct: (node) => node.isIncluded = node.originalName.startsWith('Fa'),
        enumClass: (node) {
          node.isIncluded = node.originalName.startsWith('Fa');
          node.style = EnumStyle.intConstants;
        },
        macroConstant: (node) => node.isIncluded = node.originalName.startsWith('FA_'),
      ),
    ],
  );
  await generator.generate();
}
